// Generates the panel's logo mark and icons from the mobile app's seal.
// Run from admin/: npm run branding. Source: mobile/assets/branding/splash-icon.png (tracked,
// transparent, 1024 px; itself generated by mobile/scripts/make-branding.mjs).
// sharp comes with Next.js; it is not a direct dependency.
import { writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import sharp from 'sharp';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SOURCE = path.join(ROOT, '..', 'mobile', 'assets', 'branding', 'splash-icon.png');
const APP = path.join(ROOT, 'app');

// The navy of the seal's ring; the same as the mobile app icon.
const NAVY = '#03224B';

const seal = (size) => sharp(SOURCE).resize(size, size, { kernel: 'lanczos3' });

// The source is a palette PNG, so sharp keeps writing palette PNGs.
async function write(file, image) {
  const out = await image.png({ compressionLevel: 9, effort: 10 }).toBuffer();
  await writeFile(file, out);
  console.log(`${path.relative(ROOT, file).padEnd(36)} ${(out.length / 1024).toFixed(1)} KB`);
}

/**
 * An ICO file holding PNG images (supported by every current browser): a 6-byte header,
 * one 16-byte directory entry per image, then the PNG data.
 */
function ico(pngs) {
  const header = Buffer.alloc(6 + 16 * pngs.length);
  header.writeUInt16LE(0, 0); // reserved
  header.writeUInt16LE(1, 2); // type: icon
  header.writeUInt16LE(pngs.length, 4);
  let offset = header.length;
  pngs.forEach(({ size, data }, i) => {
    const entry = 6 + 16 * i;
    header.writeUInt8(size >= 256 ? 0 : size, entry); // width (0 means 256)
    header.writeUInt8(size >= 256 ? 0 : size, entry + 1); // height
    header.writeUInt8(0, entry + 2); // no palette
    header.writeUInt8(0, entry + 3); // reserved
    header.writeUInt16LE(1, entry + 4); // colour planes
    header.writeUInt16LE(32, entry + 6); // bits per pixel
    header.writeUInt32LE(data.length, entry + 8);
    header.writeUInt32LE(offset, entry + 12);
    offset += data.length;
  });
  return Buffer.concat([header, ...pngs.map((p) => p.data)]);
}

// UI mark: shown at 36 px (size-9); 108 px covers 3x screens.
await write(path.join(ROOT, 'components', 'brand', 'unm-mark.png'), seal(108));

// Tab and PWA icon: the transparent seal.
await write(path.join(APP, 'icon.png'), seal(512));

// iOS home screen: opaque navy square (iOS fills transparency with black), seal at 84%.
const apple = await seal(152).toBuffer();
await write(
  path.join(APP, 'apple-icon.png'),
  sharp({ create: { width: 180, height: 180, channels: 4, background: NAVY } }).composite([{ input: apple, gravity: 'centre' }]).flatten({ background: NAVY }),
);

const sizes = [16, 32, 48];
const pngs = await Promise.all(sizes.map(async (size) => ({ size, data: await seal(size).png({ compressionLevel: 9 }).toBuffer() })));
const favicon = ico(pngs);
await writeFile(path.join(APP, 'favicon.ico'), favicon);
console.log(`${'app/favicon.ico'.padEnd(36)} ${(favicon.length / 1024).toFixed(1)} KB  (${sizes.join(', ')} px)`);
